<?php
$racks=rackRows();$zone=param('zona');$filtered=array_values(array_filter($racks,fn($r)=>$zone===''||$r['zona']===$zone));
$edit=param('edit')?row('SELECT * FROM rak_gudang WHERE id_rak=?',[(int)param('edit')]):null;
heading('','Rak Gudang','Lihat isi rak dan sisa kapasitas penyimpanan.',modalButton('Tambah rak','rak-form'));
$total=array_sum(array_column($racks,'kapasitas_maks_kg'));$used=array_sum(array_column($racks,'kapasitas_terpakai_kg'));
stats([['Rak penyimpanan',num(count($racks)),'Tersebar di '.count(array_unique(array_column($racks,'zona'))).' zona','rack','orange'],['Kapasitas total',kg($total),'Batas penyimpanan seluruh rak','box','blue'],['Beban terpakai',kg($used),'Berdasarkan alokasi aktif','in','purple'],['Ruang tersedia',kg($total-$used),'Siap menerima paket baru','check','green']]);
?>
<div class="section-toolbar"><div class="zone-tabs"><a class="<?=$zone===''?'selected':''?>" href="<?=e(url('rak'))?>">Semua zona</a><?php foreach(array_unique(array_column($racks,'zona')) as $z):?><a class="<?=$zone===$z?'selected':''?>" href="<?=e(url('rak',['zona'=>$z]))?>"><?=e($z)?></a><?php endforeach;?></div><span class="muted"><?=count($filtered)?> rak</span></div>
<div class="rack-grid"><?php foreach($filtered as $r):$pct=(float)$r['kapasitas_maks_kg']>0?(float)$r['kapasitas_terpakai_kg']/(float)$r['kapasitas_maks_kg']*100:0;$bad=abs((float)$r['berat_aktual']-(float)$r['kapasitas_terpakai_kg'])>0.001;$pack=rows("SELECT p.no_resi,p.berat_kg FROM alokasi_rak a JOIN paket p USING(no_resi) WHERE a.id_rak=? AND a.status_alokasi='Aktif'",[$r['id_rak']]);?><article class="panel rack-card"><div class="rack-card-head"><span class="rack-illustration"><?=icon('rack')?></span><span class="badge <?=$bad?'red':($pct>=90?'orange':'green')?>"><i></i><?=$bad?'Periksa data':($pct>=100?'Penuh':($pct>=90?'Hampir penuh':'Tersedia'))?></span></div><h2><?=e($r['kode_rak'])?></h2><p class="muted"><?=icon('pin')?><?=e($r['zona'])?> <span>·</span> <?=$r['jumlah_paket']?> paket</p><div class="rack-meter-label"><strong><?=kg($r['kapasitas_terpakai_kg'])?></strong><span><?=num($pct,1)?>%</span></div><div class="meter"><span class="<?=$pct>=90?'warning':''?>" style="width:<?=max(0,min(100,$pct))?>%"></span></div><div class="rack-meter-foot"><span>Kapasitas <?=kg($r['kapasitas_maks_kg'])?></span><span>Sisa <?=kg((float)$r['kapasitas_maks_kg']-(float)$r['kapasitas_terpakai_kg'])?></span></div><details><summary>Lihat paket tersimpan (<?=$r['jumlah_paket']?>)</summary><div class="rack-packages"><?php if(!$pack)echo '<p class="muted">Rak belum terisi.</p>';foreach($pack as $p):?><a href="<?=e(url('paket',['resi'=>$p['no_resi']]))?>"><span><?=e($p['no_resi'])?></span><span><?=kg($p['berat_kg'])?></span></a><?php endforeach;?></div></details><div class="rack-card-actions"><a href="<?=e(url('rak',['edit'=>$r['id_rak'],'open'=>'rak-form']))?>" class="button small secondary"><?=icon('edit')?>Edit rak</a><?=actionForm('rak_delete','rak',['id_rak'=>$r['id_rak']],'Hapus','trash',true)?></div></article><?php endforeach;?></div>
<?php if(!$filtered)emptyState('Belum ada rak');
beginDialog('rak-form',$edit?'Edit rak penyimpanan':'Tambah rak penyimpanan','Kapasitas dihitung berdasarkan berat dalam kilogram.','rak_save','rak');
echo '<input type="hidden" name="id_rak" value="'.e($edit['id_rak']??'').'">';field('kode_rak','Kode rak',$edit['kode_rak']??'','text',true,20);field('zona','Zona',$edit['zona']??'','text',true,20);field('kapasitas_maks_kg','Kapasitas maksimal (kg)',$edit['kapasitas_maks_kg']??'','number',true,10,'min="0.01" max="9999.99" step="0.01"');echo '<p class="form-note">Kapasitas terpakai dikelola otomatis dari transaksi paket.</p>';endDialog();
?>
